const unicornMove = () => {
    const terminal = PANEL_TERMINAL[PANEL_MAP[unicorn.panel]];
    if (unicorn.direction == 'N') {
        if (unicorn.y > 24 || (unicorn.y > 1 && terminal[0] !== undefined)) {
            unicorn.y--;
        } else {
            if (unicorn.y == 1) {
                if (
                    unicorn.panel >> 2 > 0 &&
                    terminal[0] == PANEL_TERMINAL[PANEL_MAP[unicorn.panel - 4]][1]
                ) {
                    unicorn.panel -= 4;
                    unicorn.y = 48;
                } else {
                    unicorn.direction = 'S';
                }
                unicorn.energy--;
                unicorn.face = unicorn.energy == 0 ? 'sad' : '';
            } else {
                unicorn.direction = terminal[2] !== undefined ? 'W' : 'E';
            }
        }
    }
    if (unicorn.direction == 'S') {
        if (unicorn.y < 24 || (unicorn.y < 47 && terminal[1] !== undefined)) {
            unicorn.y++;
        } else {
            if (unicorn.y == 47) {
                if (
                    unicorn.panel >> 2 < 3 &&
                    terminal[1] == PANEL_TERMINAL[PANEL_MAP[unicorn.panel + 4]][0]
                ) {
                    unicorn.panel += 4;
                    unicorn.y = 0;
                } else {
                    unicorn.direction = 'N';
                }
                unicorn.energy--;
                unicorn.face = unicorn.energy == 0 ? 'sad' : '';
            } else {
                unicorn.direction = terminal[2] !== undefined ? 'W' : 'E';
            }
        }
    }
    if (unicorn.direction == 'W') {
        unicorn.lr = 'L';
        if (unicorn.x > 32 || (unicorn.x > 1 && terminal[2] !== undefined)) {
            unicorn.x--;
        } else {
            if (unicorn.x == 1) {
                if (
                    unicorn.panel % 4 > 0 &&
                    terminal[2] == PANEL_TERMINAL[PANEL_MAP[unicorn.panel - 1]][3]
                ) {
                    unicorn.panel--;
                    unicorn.x = 64;
                } else {
                    unicorn.direction = 'E';
                }
                unicorn.energy--;
                unicorn.face = unicorn.energy == 0 ? 'sad' : '';
            } else {
                unicorn.direction = terminal[0] !== undefined ? 'N' : 'S';
            }
        }
    }
    if (unicorn.direction == 'E') {
        unicorn.lr = 'R';
        if (unicorn.x < 32 || (unicorn.x < 63 && terminal[3] !== undefined)) {
            unicorn.x++;
        } else {
            if (unicorn.x == 63) {
                if (
                    unicorn.panel % 4 < 3 &&
                    terminal[3] == PANEL_TERMINAL[PANEL_MAP[unicorn.panel + 1]][2]
                ) {
                    unicorn.panel++;
                    unicorn.x = 0;
                } else {
                    unicorn.direction = 'W';
                }
                unicorn.energy--;
                unicorn.face = unicorn.energy == 0 ? 'sad' : '';
            } else {
                unicorn.direction = terminal[0] !== undefined ? 'N' : 'S';
            }
        }
    }
};

const panelMove = (clickCol, clickRow) => {
    const clickMapId = clickRow * 4 + clickCol;
    const removalCol = REMOVAL_MAP_ID % 4;
    const removalRow = REMOVAL_MAP_ID >> 2;

    const unicornCol = unicorn.panel % 4;
    const unicornRow = unicorn.panel >> 2;

    if (clickRow > 3) return;

    // vertical slide
    if (clickCol == removalCol) {
        // north
        if (clickRow > removalRow) {
            for (let i = removalRow + 1; i <= clickRow; i++) {
                PANEL_MAP[(i - 1) * 4 + clickCol] = PANEL_MAP[i * 4 + clickCol];
            }
            REMOVAL_MAP_ID = clickMapId;
            if (unicornCol == clickCol && unicornRow > removalRow && unicornRow <= clickRow)
                unicorn.panel = unicorn.panel - 4;
        }
        // south
        if (clickRow < removalRow) {
            for (let i = removalRow - 1; i >= clickRow; i--) {
                PANEL_MAP[(i + 1) * 4 + clickCol] = PANEL_MAP[i * 4 + clickCol];
            }
            REMOVAL_MAP_ID = clickMapId;
            if (unicornCol == clickCol && unicornRow < removalRow && unicornRow >= clickRow)
                unicorn.panel = unicorn.panel + 4;
        }
    }
    // horizontal slide
    if (clickRow == removalRow) {
        // west
        if (clickCol > removalCol) {
            for (let i = removalCol + 1; i <= clickCol; i++) {
                PANEL_MAP[clickRow * 4 + i - 1] = PANEL_MAP[clickRow * 4 + i];
            }
            REMOVAL_MAP_ID = clickMapId;
            if (unicornRow == clickRow && unicornCol > removalCol && unicornCol <= clickCol)
                unicorn.panel = unicorn.panel - 1;
        }
        // east
        if (clickCol < removalCol) {
            for (let i = removalCol - 1; i >= clickCol; i--) {
                PANEL_MAP[clickRow * 4 + i + 1] = PANEL_MAP[clickRow * 4 + i];
            }
            REMOVAL_MAP_ID = clickMapId;
            if (unicornRow == clickRow && unicornCol < removalCol && unicornCol >= clickCol)
                unicorn.panel = unicorn.panel + 1;
        }
    }
    PANEL_MAP[REMOVAL_MAP_ID] = removalPid;
    // console.log('clickMapId: ' + clickMapId, 'removalMapId: ' + removalMapId);
    BG0 = setBg();

    drawBG();
};

